import styled from '@emotion/styled';

export const StyledTimePeriodChangedAlertContainer = styled.div({
  position: 'fixed',
  top: '72px',
  right: '16px',
  zIndex: 111,

  '& > div': {
    boxSizing: 'border-box',
    width: '509px',
    minWidth: '320px',
    padding: '16px',
    gap: '12px',
    backgroundColor: '#fff4e6',
    border: '1px solid #ffd499',
    boxShadow: '0 0 4px rgba(0, 0, 0, 0.16)',
    borderRadius: '8px',
  },

  '@media (max-width: 560px)': {
    right: '16px',
    left: '16px',

    '& > div': {
      width: '100%',
      minWidth: '0',
      height: 'auto',
      minHeight: '136px',
    },
  },
});
